import { format, isValid, parse } from "date-fns";

export const ISO_DATE = "yyyy-MM-dd";
export const ISO_DATE_TIME = "yyyy-MM-dd'T'HH:mm";

/** ISO 字符串 → Date；空串/非法输入返回 undefined。不用 `new Date(string)`，纯日期
 * 字符串按 UTC 解析，正时区显示会串前一天。 */
export function parseIso(value: string | undefined, pattern: string): Date | undefined {
  if (!value) return undefined;
  const parsed = parse(value, pattern, new Date());
  return isValid(parsed) ? parsed : undefined;
}

/** Date → ISO 字符串；undefined → ""（表单空值语义，与 DTO 可选字段对齐）。 */
export function formatIso(date: Date | undefined, pattern: string): string {
  return date ? format(date, pattern) : "";
}

import type { Locale } from "date-fns";
import { format } from "date-fns";
import { useMemo } from "react";

/** 年下拉里的年份跨度：当年往前 10 年、往后 1 年。这是界面可选范围，不是业务参数——补一条几个
 *  季度前的记录要往回翻几十个月，逐月点太慢。当前值落在范围外时由 `widenBounds` 撑开。 */
const YEARS_BACK = 10;
const YEARS_AHEAD = 1;

export interface CalendarBounds {
  startMonth: Date;
  endMonth: Date;
}

export function calendarBounds(today: Date): CalendarBounds {
  const year = today.getFullYear();
  return {
    startMonth: new Date(year - YEARS_BACK, 0, 1),
    endMonth: new Date(year + YEARS_AHEAD, 11, 1),
  };
}

/** 模块加载时算一次：日历每渲染重算会让 `startMonth`/`endMonth` 每次都是新引用，
 *  react-day-picker 据此重置当前显示的月份。跨年那天重开页面即更新。 */
const CALENDAR_BOUNDS = calendarBounds(new Date());

const monthStart = (date: Date) => new Date(date.getFullYear(), date.getMonth(), 1);

/** 把范围撑到能装下给定日期所在的月；都在范围内时原样返回同一个对象，保住引用。
 *  不撑的话，一条十五年前的生日在日历里根本翻不到，打开时还会被夹到下界。 */
export function widenBounds(
  bounds: CalendarBounds,
  dates: readonly (Date | undefined)[],
): CalendarBounds {
  let { startMonth, endMonth } = bounds;
  for (const date of dates) {
    if (date === undefined) continue;
    const month = monthStart(date);
    if (month < startMonth) startMonth = month;
    if (month > endMonth) endMonth = month;
  }
  return startMonth === bounds.startMonth && endMonth === bounds.endMonth
    ? bounds
    : { startMonth, endMonth };
}

const monthKey = (date: Date | undefined) =>
  date === undefined ? null : date.getFullYear() * 12 + date.getMonth();

const fromKey = (key: number | null) =>
  key === null ? undefined : new Date(Math.floor(key / 12), key % 12, 1);

/** 日历的可选范围，撑到能装下当前值。只在所涉月份变化时才换引用（同月里改日、改时分不换）。 */
export function useCalendarBounds(first?: Date, last?: Date): CalendarBounds {
  const firstKey = monthKey(first);
  const lastKey = monthKey(last);
  return useMemo(
    () => widenBounds(CALENDAR_BOUNDS, [fromKey(firstKey), fromKey(lastKey)]),
    [firstKey, lastKey],
  );
}

const monthFormatters = new Map<
  Locale | undefined,
  { formatMonthDropdown: (date: Date) => string }
>();

/** 年月下拉里的月份名。shadcn 的 Calendar 默认用 `toLocaleString("default", …)` 格式化月份下拉，
 *  走的是运行时 locale 而不是日历自己的 `locale`，中文界面里会冒出 Jan…Dec。按 locale 缓存：
 *  每渲染新建对象会让 react-day-picker 每次都拿到新的 formatters 引用。 */
export function calendarFormatters(locale: Locale | undefined) {
  let cached = monthFormatters.get(locale);
  if (!cached) {
    cached = { formatMonthDropdown: (date: Date) => format(date, "LLL", { locale }) };
    monthFormatters.set(locale, cached);
  }
  return cached;
}

import { useCulture, useLocalization } from "@jcoder-stack/abp-react/react";
import type { Locale } from "date-fns";
import { format } from "date-fns";
import { zhCN } from "date-fns/locale";
import { CalendarIcon } from "lucide-react";
import { useState } from "react";
import { calendarFormatters, useCalendarBounds } from "@/components/date-picker/calendar-bounds";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/** culture → date-fns locale；未映射的 culture 返回 undefined（= react-day-picker 默认 enUS）。
 * 只影响展示格式，存储值恒为 ISO 字符串（见 date-io.ts）。 */
export function dateFnsLocale(culture: string): Locale | undefined {
  return culture === "zh-Hans" ? zhCN : undefined;
}

export interface DatePickerProps {
  value?: Date;
  onChange: (date: Date | undefined) => void;
  id?: string;
  disabled?: boolean;
  placeholder?: string;
  "aria-invalid"?: boolean;
  "aria-required"?: boolean;
}

export function DatePicker(props: DatePickerProps) {
  const L = useLocalization();
  const culture = useCulture();
  const [open, setOpen] = useState(false);
  const locale = dateFnsLocale(culture);
  const bounds = useCalendarBounds(props.value);
  const label = props.value
    ? format(props.value, "PPP", { locale })
    : (props.placeholder ?? L("DatePicker:Placeholder"));
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          id={props.id}
          type="button"
          variant="outline"
          disabled={props.disabled}
          aria-invalid={props["aria-invalid"] || undefined}
          aria-required={props["aria-required"] || undefined}
          // 窄容器里格式化后的日期常超出按钮宽度；Button 的 whitespace-nowrap 会直接裁断，
          // 故文本自己 truncate，完整值走 title。占位文案没有「完整值」可揭示，不给 title。
          title={props.value ? label : undefined}
          className={cn(
            "w-full justify-start text-left font-normal",
            !props.value && "text-muted-foreground",
          )}
        >
          <CalendarIcon className="size-4" />
          <span className="min-w-0 truncate">{label}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={props.value}
          // 不给锚点时日历停在当前月，编辑一条旧记录要手动往回翻几十个月才见到原值。
          // defaultMonth 只在挂载时读一次，而 Popover 关闭即卸载内容，于是每次打开都按
          // 当时的 value 重新起锚，用户上一次翻到的月份不会残留。
          defaultMonth={props.value}
          onSelect={(date) => {
            props.onChange(date);
            setOpen(false);
          }}
          // 年月下拉：往回补一条几个月前的记录时，逐月点太慢
          captionLayout="dropdown"
          startMonth={bounds.startMonth}
          endMonth={bounds.endMonth}
          formatters={calendarFormatters(locale)}
          locale={locale}
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}

import { useCulture, useLocalization } from "@jcoder-stack/abp-react/react";
import { format } from "date-fns";
import { CalendarIcon } from "lucide-react";
import { useState } from "react";
import { calendarFormatters, useCalendarBounds } from "@/components/date-picker/calendar-bounds";
import { dateFnsLocale } from "@/components/date-picker/date-picker";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

export interface DateRange {
  from?: Date;
  to?: Date;
}

/** 只有起止都齐全才算日历可继续拼接的锚点；只给了 from 的半截值会被
 * react-day-picker 的 addToRange 当成「已有起点」，下一次点选立刻收尾成
 * from～该天，无法再分两步选出真正的止点，故半截值一律当空处理。 */
function toCalendarRange(range: DateRange | undefined): DateRange | undefined {
  return range?.from !== undefined && range.to !== undefined ? range : undefined;
}

export interface DateRangePickerProps {
  value?: DateRange;
  onChange: (range: DateRange | undefined) => void;
  id?: string;
  disabled?: boolean;
  placeholder?: string;
  "aria-invalid"?: boolean;
  "aria-required"?: boolean;
}

export function DateRangePicker(props: DateRangePickerProps) {
  const L = useLocalization();
  const culture = useCulture();
  const [open, setOpen] = useState(false);
  const [working, setWorking] = useState(() => toCalendarRange(props.value));
  const locale = dateFnsLocale(culture);
  const bounds = useCalendarBounds(props.value?.from, props.value?.to);
  const { value } = props;
  const label =
    value?.from !== undefined
      ? `${format(value.from, "PP", { locale })} – ${
          value.to !== undefined ? format(value.to, "PP", { locale }) : ""
        }`
      : (props.placeholder ?? L("DatePicker:RangePlaceholder"));
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        // 打开瞬间用最新受控 value 重新起锚；打开期间的中间选区只活在 working
        // 里，不受父组件重渲染影响，两次点选之间不会被打断。
        if (next) setWorking(toCalendarRange(value));
      }}
    >
      <PopoverTrigger asChild>
        <Button
          id={props.id}
          type="button"
          variant="outline"
          disabled={props.disabled}
          aria-invalid={props["aria-invalid"] || undefined}
          aria-required={props["aria-required"] || undefined}
          // 区间文本是两个完整日期，窄容器里必然超宽；Button 的 whitespace-nowrap 会直接裁断，
          // 故文本自己 truncate，完整区间走 title。占位文案没有「完整值」可揭示，不给 title。
          title={value?.from !== undefined ? label : undefined}
          className={cn(
            "w-full justify-start text-left font-normal",
            value?.from === undefined && "text-muted-foreground",
          )}
        >
          <CalendarIcon className="size-4" />
          <span className="min-w-0 truncate">{label}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="range"
          numberOfMonths={2}
          // 相邻两个月的网格互相包含对方的溢出日，开启溢出日时同一天会在两处都带上选中高亮，
          // 看起来是重复的一天、区间断成两截。
          showOutsideDays={false}
          resetOnSelect
          // 见 date-picker.tsx：按起始日起锚（numberOfMonths=2 时它是左侧那个月）。锚点取
          // 用 props.value 而不是 working，半截区间的 working 被归零，仍应停在用户已选的起始月。
          defaultMonth={value?.from}
          // 见 date-picker.tsx：年月下拉，范围撑到能装下当前区间
          captionLayout="dropdown"
          startMonth={bounds.startMonth}
          endMonth={bounds.endMonth}
          formatters={calendarFormatters(locale)}
          selected={working ? { from: working.from, to: working.to } : undefined}
          onSelect={(range) => {
            setWorking(range);
            props.onChange(range);
            if (range?.from !== undefined && range?.to !== undefined) setOpen(false);
          }}
          locale={locale}
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}

import { useCulture, useLocalization } from "@jcoder-stack/abp-react/react";
import { format } from "date-fns";
import { CalendarIcon } from "lucide-react";
import { useState } from "react";
import { calendarFormatters, useCalendarBounds } from "@/components/date-picker/calendar-bounds";
import type { DatePickerProps } from "@/components/date-picker/date-picker";
import { dateFnsLocale } from "@/components/date-picker/date-picker";
import { TimeInput } from "@/components/date-picker/time-input";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/** 把 "HH:mm" 拼进 date 的时分（date 拷贝构造，不改动原引用）。 */
function mergeTime(date: Date, time: string): Date {
  const [hours = 0, minutes = 0] = time.split(":").map(Number);
  const merged = new Date(date);
  merged.setHours(hours, minutes, 0, 0);
  return merged;
}

export function DateTimePicker(props: DatePickerProps) {
  const L = useLocalization();
  const culture = useCulture();
  const [open, setOpen] = useState(false);
  const locale = dateFnsLocale(culture);
  const bounds = useCalendarBounds(props.value);
  const timeValue = props.value ? format(props.value, "HH:mm") : "";
  const label = props.value
    ? // 时分固定 24 小时制：locale 的 `p` 在中文下是「上午 12:00」，与全站的 `HH:mm` 不是一套读法
      `${format(props.value, "PP", { locale })} ${format(props.value, "HH:mm")}`
    : (props.placeholder ?? L("DatePicker:Placeholder"));
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          id={props.id}
          type="button"
          variant="outline"
          disabled={props.disabled}
          aria-invalid={props["aria-invalid"] || undefined}
          aria-required={props["aria-required"] || undefined}
          // 日期加时分比单日期更长，窄容器里必然超宽；Button 的 whitespace-nowrap 会直接裁断，
          // 故文本自己 truncate，完整值走 title。占位文案没有「完整值」可揭示，不给 title。
          title={props.value ? label : undefined}
          className={cn(
            "w-full justify-start text-left font-normal",
            !props.value && "text-muted-foreground",
          )}
        >
          <CalendarIcon className="size-4" />
          <span className="min-w-0 truncate">{label}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={props.value}
          // 见 date-picker.tsx：挂载时按 value 起锚，弹层每次打开都重新定位。这里 value 会
          // 随时间输入变化，而 defaultMonth 只读挂载那一次，故改时分不会把日历甩走。
          defaultMonth={props.value}
          onSelect={(date) => {
            if (date === undefined) {
              props.onChange(undefined);
              return;
            }
            props.onChange(timeValue === "" ? date : mergeTime(date, timeValue));
          }}
          // 见 date-picker.tsx：年月下拉，范围撑到能装下当前值
          captionLayout="dropdown"
          startMonth={bounds.startMonth}
          endMonth={bounds.endMonth}
          formatters={calendarFormatters(locale)}
          locale={locale}
          autoFocus
        />
        <div className="border-t p-3">
          <TimeInput
            aria-label={L("DatePicker:Time")}
            value={timeValue}
            onChange={(time) => {
              // 清空时分只是「没填时分」，不该把已选的日期一起清掉
              if (time === "") return;
              props.onChange(mergeTime(props.value ?? new Date(), time));
            }}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

import { useEffect, useState } from "react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

const HOUR_DIGITS = 2;
const MAX_DIGITS = 4;

/** 边敲边整形：只留数字，够两位就补冒号，最多四位。 */
export function maskTimeInput(text: string): string {
  const digits = text.replace(/\D/g, "").slice(0, MAX_DIGITS);
  if (digits.length <= HOUR_DIGITS) return digits;
  return `${digits.slice(0, HOUR_DIGITS)}:${digits.slice(HOUR_DIGITS)}`;
}

/**
 * 把输入整理成 `HH:mm`，整理不出来时返回 null。
 * 只给一两位数字时按小时理解（`9` → `09:00`），敲 `930` 的意思是 9 点半。
 */
export function normalizeTime(text: string): string | null {
  const digits = text.replace(/\D/g, "");
  if (digits.length === 0) return null;
  const padded =
    digits.length <= HOUR_DIGITS
      ? `${digits.padStart(HOUR_DIGITS, "0")}00`
      : digits.padStart(MAX_DIGITS, "0");
  const hour = Number(padded.slice(0, HOUR_DIGITS));
  const minute = Number(padded.slice(HOUR_DIGITS));
  if (hour > 23 || minute > 59) return null;
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

/**
 * 失焦时该落成什么值。
 *
 * 整理不出来时保留表单里的原值：清空一个看不懂的时刻，等于在用户只是点了一下的情况下把它悄悄
 * 删掉，而后端跨天的 TimeSpan（`d.HH:mm`）正好长成这样。空输入是明确要清掉，照办。
 */
export function resolveTimeOnBlur(text: string, current: string): string {
  if (text.trim() === "") return "";
  return normalizeTime(text) ?? current;
}

/**
 * 24 小时制的时分输入，显示与取值恒为 `HH:mm`（空串表示未填）。
 *
 * 原生 `<input type="time">` 的 12/24 制跟浏览器区域设置走，不受页面 `lang` 控制：中文界面上会
 * 渲染成 `05:30 PM`，与系统其余地方的 `17:30` 不是一套读法；弹出的时分列表是浏览器自绘的，
 * 无法主题化。这里换成受控文本框。
 */
export function TimeInput(props: {
  id?: string;
  name?: string;
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
  "aria-required"?: boolean;
  "aria-invalid"?: boolean;
}) {
  const [text, setText] = useState(props.value);
  // 外部改了值（换一天、表单重置）要跟上；正在敲的中间态由 onChange 自己维护
  useEffect(() => setText(props.value), [props.value]);

  return (
    <Input
      id={props.id}
      name={props.name}
      inputMode="numeric"
      placeholder="--:--"
      className={cn("tabular-nums", props.className)}
      value={text}
      disabled={props.disabled}
      aria-label={props["aria-label"]}
      aria-required={props["aria-required"]}
      aria-invalid={props["aria-invalid"]}
      // 聚焦即全选：已有 `00:00` 时直接敲 `930` 要整体替换，否则新数字追加在后面、被掩码截掉
      onFocus={(event) => event.currentTarget.select()}
      onChange={(event) => {
        const masked = maskTimeInput(event.target.value);
        setText(masked);
        // 敲满四位才往外发，半截的 `09:3` 会被上游当成一个时刻
        const normalized = masked.length === 5 ? normalizeTime(masked) : null;
        if (normalized !== null) props.onChange(normalized);
        if (masked === "") props.onChange("");
      }}
      onBlur={() => {
        const resolved = resolveTimeOnBlur(text, props.value);
        setText(resolved);
        props.onChange(resolved);
        props.onBlur?.();
      }}
    />
  );
}

